", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\jsondiff-1794053379\\jsondiff.py","content":"\"\"\"Structural JSON diff using only the standard library.\"\"\"\n\nimport json\n\n\ndef diff(a, b):\n    \"\"\"Return a sorted list of strings describing how to get from `a` to `b`.\"\"\"\n    out = []\n    _diff(a, b, \"$\", out)\n    out.sort()\n    return out\n\n\ndef _kind(value):\n    if isinstance(value, dict):\n        return \"dict\"\n    if isinstance(value, list):\n        return \"list\"\n    return \"scalar\"\n\n\ndef _same(a, b):\n    \"\"\"Equal only when the same type and the values compare equal.\"\"\"\n    if type(a) is not type(b):\n        return False\n    return a == b\n\n\ndef _dump(value):\n    return json.dumps(value, sort_keys=True)\n\n\ndef _diff(a, b, path, out):\n    ka, kb = _kind(a), _kind(b)\n\n    if ka == \"scalar\" and kb == \"scalar\":\n        if not _same(a, b):\n            out.append(\"~ %s: %s -> %s\" % (path, _dump(a), _dump(b)))\n        return\n\n    if ka == \"dict\" and kb == \"dict\":\n        for key in a:\n            child = \"%s.%s\" % (path, key)\n            if key in b:\n                _diff(a[key], b[key], child, out)\n            else:\n                out.append(\"- %s: %s\" % (child, _dump(a[key])))\n        for key in b:\n            if key not in a:\n                out.append(\"+ %s.%s: %s\" % (path, key, _dump(b[key])))\n        return\n\n    if ka == \"list\" and kb == \"list\":\n        shared = min(len(a), len(b))\n        for i in range(shared):\n            _diff(a[i], b[i], \"%s[%d]\" % (path, i), out)\n        for i in range(shared, len(a)):\n            out.append(\"- %s[%d]: %s\" % (path, i, _dump(a[i])))\n        for i in range(shared, len(b)):\n            out.append(\"+ %s[%d]: %s\" % (path, i, _dump(b[i])))\n        return\n\n    # Different kinds of values (including container vs non-container).\n    out.append(\"~ %s: %s -> %s\" % (path, _dump(a), _dump(b)))\n"}"]]}

